	ID      string
	Payload string
}

func Deliver(events []Event, handle func(Event), complete func(int)) {
	seen := make(map[string]struct{}, len(events))
	delivered := 0
	for _, event := range events {
		if _, exists := seen[event.ID]; exists {
			continue
		}
		seen[event.ID] = struct{}{}
		handle(event)
		delivered++
	}
	complete(delivered)
}
