```go
package solution

type Listener struct {
	ID     string
	Handle func(string)
}

func Broadcast(listeners []Listener, messages []string, done func(string, int)) {
	byID := make(map[string]Listener, len(listeners))
	order := make([]string, 0, len(listeners))
	for _, listener := range listeners {
		if _, exists := byID[listener.ID]; !exists {
			order = append(order, listener.ID)
		}
		byID[listener.ID] = listener
	}

	for _, message := range messages {
		for _, id := range order {
			byID[id].Handle(message)
		}
	}
	for _, id := range order {
		done(id, len(messages))
	}
}
