import (
	"strconv"
	"strings"
	"testing"
)

func treeShape(node *TreeNode) string {
	if node == nil {
		return "#"
	}
	var b strings.Builder
	b.WriteString(strconv.Quote(node.Label))
	b.WriteByte('[')
	for i, child := range node.Children {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(treeShape(child))
	}
	b.WriteByte(']')
	return b.String()
}

func collectTreeNodes(node *TreeNode, nodes map[*TreeNode]struct{}) {
	if node == nil {
		return
	}
	nodes[node] = struct{}{}
