import "testing"

type vertexSnapshot struct {
	value string
	next  []*Vertex
}

func snapshotGraph(root *Vertex) map[*Vertex]vertexSnapshot {
	result := make(map[*Vertex]vertexSnapshot)
	var visit func(*Vertex)
	visit = func(node *Vertex) {
		if node == nil {
			return
		}
		if _, seen := result[node]; seen {
			return
		}
		result[node] = vertexSnapshot{value: node.Value, next: append([]*Vertex(nil), node.Next...)}
		for _, next := range node.Next {
			visit(next)
		}
	}
	visit(root)
	return result
}

func assertGraphUnchanged(t *testing.T, snapshots map[*Vertex]vertexSnapshot) {
	t.Helper()
	for node, snapshot := range snapshots {
		if node.Value != snapshot.value {
			t.Fatalf("input value changed from %q to %q", snapshot.value, node.Value)
		}
		if len(node.Next) != len(snapshot.next) {
			t.Fatalf("input Next length changed for %q", snapshot.value)
		}
		for i := range snapshot.next {
			if node.Next[i] != snapshot.next[i] {
				t.Fatalf("input edge %q[%d] was modified", snapshot.value, i)
			}
		}
	}
}

func assertGraphClone(t *testing.T, input, output *Vertex) map[*Vertex]*Vertex {
	t.Helper()
	inputNodes := snapshotGraph(input)
	forward := make(map[*Vertex]*Vertex)
	reverse := make(map[*Vertex]*Vertex)
	var compare func(*Vertex, *Vertex)
	compare = func(in, out *Vertex) {
		if in == nil || out == nil {
			if in != nil || out != nil {
				t.Fatalf("nil edge mismatch: input=%p output=%p", in, out)
			}
			return
		}
		if _, aliasesInput := inputNodes[out]; aliasesInput {
			t.Fatalf("output vertex %p aliases an input vertex", out)
		}
		if previous, seen := forward[in]; seen {
			if previous != out {
				t.Fatalf("input vertex %q maps to multiple output vertices", in.Value)
			}
			return
		}
		if previous, seen := reverse[out]; seen && previous != in {
			t.Fatalf("distinct input vertices share output vertex %p", out)
		}
		forward[in] = out
		reverse[out] = in
		if in.Value != out.Value {
			t.Fatalf("value mismatch: got %q, want %q", out.Value, in.Value)
		}
		if len(in.Next) != len(out.Next) {
			t.Fatalf("Next length for %q = %d, want %d", in.Value, len(out.Next), len(in.Next))
		}
		if len(in.Next) > 0 && &in.Next[0] == &out.Next[0] {
			t.Fatalf("Next slice for %q aliases the input slice", in.Value)
		}
		for i := range in.Next {
			compare(in.Next[i], out.Next[i])
		}
	}
	compare(input, output)
	if len(forward) != len(inputNodes) {
		t.Fatalf("cloned %d reachable vertices, want %d", len(forward), len(inputNodes))
	}
	return forward
}

func TestCloneReachablePreservesCyclesSharingNilEdgesAndOrder(t *testing.T) {
	a := &Vertex{Value: "a", Next: make([]*Vertex, 4)}
	b := &Vertex{Value: "b", Next: make([]*Vertex, 2)}
	c := &Vertex{Value: "c", Next: make([]*Vertex, 1)}
	a.Next[0], a.Next[1], a.Next[2], a.Next[3] = b, nil, c, b
	b.Next[0], b.Next[1] = a, c
	c.Next[0] = c
	snapshots := snapshotGraph(a)

	clone := CloneReachable(a)

	assertGraphUnchanged(t, snapshots)
	mapping := assertGraphClone(t, a, clone)
	if clone.Next[0] != clone.Next[3] {
		t.Fatal("shared destination was not preserved")
	}
	if clone.Next[1] != nil {
		t.Fatal("nil edge was not preserved")
	}
	if mapping[c].Next[0] != mapping[c] {
		t.Fatal("self-cycle was not preserved")
	}
	if mapping[b].Next[0] != clone {
		t.Fatal("cycle back to root was not preserved")
	}

	clone.Value = "changed clone"
	clone.Next[0] = nil
	assertGraphUnchanged(t, snapshots)

	a.Value = "changed input"
	a.Next[2] = nil
	if clone.Value != "changed clone" {
		t.Fatal("changing input value affected clone")
	}
	if clone.Next[2] != mapping[c] {
		t.Fatal("changing input edge affected clone Next slice")
	}
}

func TestCloneReachableNilRoot(t *testing.T) {
	if got := CloneReachable(nil); got != nil {
		t.Fatalf("CloneReachable(nil) = %p, want nil", got)
	}
}

func TestCloneReachableDoesNotAliasEmptySliceBackingArray(t *testing.T) {
	root := &Vertex{Value: "root", Next: make([]*Vertex, 0, 2)}
	clone := CloneReachable(root)
	if clone == nil || len(clone.Next) != 0 {
		t.Fatalf("clone of empty graph node is %#v", clone)
	}
	cloneChild := &Vertex{Value: "clone child"}
	inputChild := &Vertex{Value: "input child"}
	clone.Next = append(clone.Next, cloneChild)
	root.Next = append(root.Next, inputChild)
	if clone.Next[0] != cloneChild {
		t.Fatal("empty output Next slice shares its backing array with input")
	}
}
