{"items":[{"id":"cap-v2-graph_and_tree-go-repair-02","test_code":"package solution

import (
	"reflect"
	"testing"
)

func TestAncestorPathValidChains(t *testing.T) {
	tests := []struct {
		name   string
		parent []int
		start  int
		want   []int
	}{
		{"chain to root", []int{-1, 0, 1, 2}, 3, []int{3, 2, 1, 0}},
		{"start at root", []int{-1, 0, 0}, 0, []int{0}},
		{"root at nonzero index", []int{2, 2, -1, 1}, 3, []int{3, 1, 2}},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, ok := AncestorPath(tc.parent, tc.start)
			if !ok || !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("AncestorPath(%v, %d) = (%v, %v), want (%v, true)", tc.parent, tc.start, got, ok, tc.want)
			}
		})
	}
}

func TestAncestorPathRejectsInvalidStart(t *testing.T) {
	for _, start := range []int{-1, 3} {
		got, ok := AncestorPath([]int{-1, 0, 1}, start)
		if ok || got != nil {
			t.Errorf("start %d: got (%v, %v), want (nil, false)", start, got, ok)
		}
	}

	got, ok := AncestorPath(nil, 0)
	if ok || got != nil {
		t.Errorf("empty hierarchy: got (%v, %v), want (nil, false)", got, ok)
	}
}

func TestAncestorPathRejectsInvalidFollowedParent(t *testing.T) {
	tests := []struct {
		name   string
		parent []int
		start  int
	}{
		{"parent above range", []int{-1, 3}, 1},
		{"parent below minus one", []int{-1, -2}, 1},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, ok := AncestorPath(tc.parent, tc.start)
			if ok || got != nil {
				t.Fatalf("got (%v, %v), want (nil, false)", got, ok)
			}
		})
	}
}

func TestAncestorPathRejectsCycles(t *testing.T) {
	tests := []struct {
		name   string
		parent []int
		start  int
	}{
		{"self cycle", []int{-1, 1}, 1},
		{"multi-node cycle", []int{-1, 2, 3, 1}, 3},
		{"tail entering cycle", []int{1, 2, 1, 2}, 3},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, ok := AncestorPath(tc.parent, tc.start)
			if ok || got != nil {
				t.Fatalf("got (%v, %v), want (nil, false)", got, ok)
			}
		})
	}
}

func TestAncestorPathIgnoresUnreachableMalformedNodesAndDoesNotMutate(t *testing.T) {
	parent := []int{-1, 0, 4, 3, 2}
	before := append([]int(nil), parent...)

	got, ok := AncestorPath(parent, 1)
	want := []int{1, 0}
	if !ok || !reflect.DeepEqual(got, want) {
		t.Fatalf("got (%v, %v), want (%v, true)", got, ok, want)
	}
	if !reflect.DeepEqual(parent, before) {
		t.Fatalf("parent mutated: got %v, want %v", parent, before)
	}
}
