		t.Fatalf("RankRowSums(nil) = %v, want empty result", got)
	}

	matrix := [][]int64{nil, {}, {1, -1}, {0}, {-1}}
	want := []int{0, 1, 2, 3, 4}
	if got := RankRowSums(matrix); !reflect.DeepEqual(got, want) {
		t.Fatalf("RankRowSums(%v) = %v, want %v", matrix, got, want)
	}
