		t.Fatalf("RankRowSums() = %v, want %v", got, want)
	}
}

func TestRankRowSumsDoesNotMutateMatrixAndIsDeterministic(t *testing.T) {
	matrix := [][]int64{{3, -1}, {1, 1}, {}, {8}}
	before := make([][]int64, len(matrix))
	for i := range matrix {
		before[i] = append([]int64(nil), matrix[i]...)
	}
	want := []int{3, 0, 1, 2}

	first := RankRowSums(matrix)
	second := RankRowSums(matrix)
